     1	// Merges the generated overrides (orca-mac-keybindings.js) into
     2	// ~/.orca/keybindings.json's platforms.linux. See orca.nix.
     3	//
     4	//   node orca-mac-keybindings-merge.js <app>/out/shared <owned.json>
     5	//
     6	// The file is Orca's read-write state, so this owns only what it wrote: a
     7	// sidecar, keybindings.nix-owned.json, records the values of the last write.
     8	//   - a key written last time and no longer generated is removed;
     9	//   - a key whose value the UI has changed since is left as the UI's;
    10	//   - with no sidecar yet, any value already on a generated key is the UI's;
    11	//   - everything else in the file is untouched.
    12	// Then the merged file gets Orca's own conflict check. Orca drops every
    13	// action in a conflicting set at load, so a generated key that clashes with
    14	// a UI shortcut is withdrawn instead, and named, leaving the UI's choice and
    15	// the generated action's Linux default.
    16	const fs = require('fs');
    17	const os = require('os');
    18	const path = require('path');
    19	
    20	// Activation runs under set -e, so a throw here would abandon the rest of
    21	// the switch over a keybinding file. Any failure is one line and exit 0;
    22	// the file is then exactly as it was, since writes only ever rename over it.
    23	process.on('uncaughtException', (e) => {
    24	  console.error(`orca: keybinding merge skipped: ${e.message}`);
    25	  process.exit(0);
    26	});
    27	
    28	const [shared, ownedFile] = process.argv.slice(2);
    29	const kb = require(path.resolve(shared, 'keybindings.js'));
    30	const owned = JSON.parse(fs.readFileSync(ownedFile, 'utf8'));
    31	
    32	const dir = path.join(os.homedir(), '.orca');
    33	const dest = path.join(dir, 'keybindings.json');
    34	const sidecar = path.join(dir, 'keybindings.nix-owned.json');
    35	const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
    36	const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
    37	
    38	// Orca's own writer (G$): whole file to a temp name, rename over, and the
    39	// temp removed if either step fails.
    40	function writeJson(file, value) {
    41	  const tmp = `${file}.nix-${process.pid}-${Date.now()}`;
    42	  try {
    43	    fs.writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, { flag: 'wx' });
    44	    fs.renameSync(tmp, file);
    45	  } catch (e) {
    46	    fs.rmSync(tmp, { force: true });
    47	    throw e;
    48	  }
    49	}
    50	
    51	fs.mkdirSync(dir, { recursive: true });
    52	let doc;
    53	if (!fs.existsSync(dest)) {
    54	  doc = { version: 1, keybindings: {}, platforms: { darwin: {}, linux: {}, win32: {} } };
    55	} else {
    56	  let why = null;
    57	  try {
    58	    doc = JSON.parse(fs.readFileSync(dest, 'utf8'));
    59	    if (!isObject(doc)) why = 'not a JSON object';
    60	  } catch (e) {
    61	    why = e.message;
    62	  }
    63	  if (why !== null) {
    64	    // Orca's loader rejects it too and says so; overwriting would lose
    65	    // whatever the user was halfway through editing.
    66	    console.error(`orca: ${dest}: ${why}; leaving it for Orca to report`);
    67	    process.exit(0);
    68	  }
    69	}
    70	
    71	// No sidecar over a file that exists: Orca (or a deleted sidecar) wrote
    72	// what is there, so nothing in it is this table's to overwrite.
    73	const adopting = fs.existsSync(dest) && !fs.existsSync(sidecar);
    74	let prev = {};
    75	try {
    76	  const s = JSON.parse(fs.readFileSync(sidecar, 'utf8'));
    77	  if (!isObject(s?.linux)) throw new Error('no .linux object');
    78	  prev = s.linux;
    79	} catch (e) {
    80	  // No sidecar is a first run. A bad one stops the merge: it decides what
    81	  // may be overwritten, and reading it as empty overwrites every key the UI
    82	  // has changed.
    83	  if (e.code !== 'ENOENT') {
    84	    console.error(`orca: ${sidecar}: ${e.message}; not merging -- delete it to start over`);
    85	    process.exit(0);
    86	  }
    87	}
    88	
    89	const platforms = isObject(doc.platforms) ? doc.platforms : {};
    90	const linux = isObject(platforms.linux) ? { ...platforms.linux } : {};
    91	// Changed since the last write: the UI's now. Absent (reset in the UI)
    92	// is not a change -- the reset target is this table, so it comes back.
    93	const theirs = new Set(
    94	  adopting
    95	    ? Object.keys(owned).filter((id) => id in linux)
    96	    : Object.keys(prev).filter((id) => id in linux && !same(linux[id], prev[id])),
    97	);
    98	for (const id of Object.keys(prev)) {
    99	  if (!theirs.has(id)) delete linux[id];
   100	}
   101	// What the UI had on each key about to be overwritten, for a withdrawal
   102	// below to put back. Stale keys are gone by now, so anything left is the UI's.
   103	const before = {};
   104	const written = {};
   105	for (const [id, bindings] of Object.entries(owned)) {
   106	  if (theirs.has(id)) continue;
   107	  if (id in linux) before[id] = linux[id];
   108	  linux[id] = bindings;
   109	  written[id] = bindings;
   110	}
   111	
   112	// What Orca's loader feeds its conflict pass: common, then the platform
   113	// section over it, with its string shorthand and null/false expanded.
   114	// Common is the root's action keys in the legacy shape with no .keybindings.
   115	const common = doc.keybindings === undefined ? doc : isObject(doc.keybindings) ? doc.keybindings : {};
   116	// Orca's loader (jHn): null/false unbind; a string is a comma list; an array
   117	// of strings may hold comma lists too; one bad chord rejects the whole value,
   118	// leaving the action on its default (undefined here).
   119	const expand = (id, v) => {
   120	  if (v === null || v === false) return [];
   121	  const n =
   122	    typeof v === 'string' ? kb.normalizeKeybindingListForAction(id, v)
   123	      : Array.isArray(v) && v.every((b) => typeof b === 'string') ? kb.normalizeKeybindingArrayForAction(id, v)
   124	        : { ok: false };
   125	  return Array.isArray(n) ? n : n.ok ? [n.value] : undefined;
   126	};
   127	// Each section parsed on its own, then layered (q$): a bad platform value is
   128	// dropped, not allowed to hide a good common one.
   129	const parse = (section) =>
   130	  Object.fromEntries(
   131	    Object.entries(section)
   132	      .filter(([id, v]) => kb.isKeybindingActionId(id) && expand(id, v) !== undefined)
   133	      .map(([id, v]) => [id, expand(id, v)]),
   134	  );
   135	const commonParsed = parse(common);
   136	const effective = { ...commonParsed, ...parse(linux) };
   137	for (;;) {
   138	  const withdrawn = kb
   139	    .findKeybindingConflicts('linux', effective)
   140	    .flatMap((c) => c.actionIds)
   141	    .filter((id) => id in written);
   142	  // Only generated keys are ever withdrawn. A conflict with none left in it
   143	  // -- between UI shortcuts, or a UI shortcut and the Linux default a
   144	  // withdrawal brought back -- is Orca's to report.
   145	  if (withdrawn.length === 0) break;
   146	  for (const id of new Set(withdrawn)) {
   147	    console.error(`orca: ${id} ${JSON.stringify(written[id])} clashes with a shortcut set in Orca; keeping that one`);
   148	    delete written[id];
   149	    if (id in before) {
   150	      linux[id] = before[id];
   151	    } else {
   152	      delete linux[id];
   153	    }
   154	    const restored = id in linux ? expand(id, linux[id]) : undefined;
   155	    if (restored !== undefined) effective[id] = restored;
   156	    else if (id in commonParsed) effective[id] = commonParsed[id];
   157	    else delete effective[id];
   158	  }
   159	}
   160	
   161	doc.version = 1;
   162	doc.platforms = {
   163	  ...platforms,
   164	  darwin: isObject(platforms.darwin) ? platforms.darwin : {},
   165	  linux,
   166	  win32: isObject(platforms.win32) ? platforms.win32 : {},
   167	};
   168	writeJson(dest, doc);
   169	// Every key this table claims, written or withdrawn, at its generated value;
   170	// the UI's keep the value last written. Either way a later UI value reads as
   171	// changed, the UI's, rather than as never owned and free to overwrite.
   172	writeJson(sidecar, {
   173	  linux: {
   174	    ...owned,
   175	    ...Object.fromEntries([...theirs].filter((id) => id in prev).map((id) => [id, prev[id]])),
   176	    ...written,
   177	  },
   178	});
   179	// Emits Orca's platforms.linux keybinding overrides: every action's macOS
   180	// default, with Mod (Cmd there, Ctrl here) spelled Cmd, which Orca binds to
   181	// Super on Linux. See orca.nix.
   182	//
   183	//   node orca-mac-keybindings.js <app>/out/shared <hyprland-chords.json>
   184	//
   185	// Uses Orca's own keybinding module (out/shared/keybindings.js, the stable
   186	// facade its comment promises) for the definitions, normalisation and the
   187	// conflict check, so a version bump regenerates the table instead of
   188	// silently drifting from it.
   189	const fs = require('fs');
   190	const path = require('path');
   191	
   192	const [shared, chordsFile] = process.argv.slice(2);
   193	const kb = require(path.resolve(shared, 'keybindings.js'));
   194	
   195	// Chords Hyprland binds never reach the window. "SUPER + SHIFT + W" ->
   196	// "Cmd+Shift+W". Mouse, switch and media-key binds cannot be an Orca chord;
   197	// anything else that does not translate is an error, not a free chord.
   198	const MODS = { SUPER: 'Cmd', CTRL: 'Ctrl', CONTROL: 'Ctrl', ALT: 'Alt', SHIFT: 'Shift' };
   199	const KEYS = { return: 'Enter', left: 'ArrowLeft', right: 'ArrowRight', up: 'ArrowUp', down: 'ArrowDown' };
   200	const taken = new Set();
   201	for (const chord of JSON.parse(fs.readFileSync(chordsFile, 'utf8'))) {
   202	  const parts = chord.split('+').map((s) => s.trim());
   203	  const key = parts.pop();
   204	  if (/^(mouse[:_]|XF86)/.test(key) || chord.startsWith('switch:')) continue;
   205	  const mods = parts.map((p) => MODS[p.toUpperCase()]);
   206	  const n = mods.every(Boolean) && kb.normalizeKeybinding([...mods, KEYS[key] ?? key].join('+'));
   207	  if (!n || !n.ok) throw new Error(`cannot translate Hyprland bind "${chord}" to an Orca chord`);
   208	  taken.add(n.value);
   209	}
   210	// A digit-index action's one binding stands for its whole 1-9 family.
   211	const isTaken = (id, binding) =>
   212	  kb.isDigitIndexActionId(id)
   213	    ? [1, 2, 3, 4, 5, 6, 7, 8, 9].some((d) => taken.has(binding.replace(/1$/, String(d))))
   214	    : taken.has(binding);
   215	
   216	const overrides = {};
   217	// Actions every one of whose Mac chords Hyprland took: left on Linux defaults.
   218	const fellBack = new Set();
   219	for (const def of kb.KEYBINDING_DEFINITIONS) {
   220	  const mac = kb.getDefaultBindings(def, 'darwin').map((binding) => {
   221	    const cmd = binding.split('+').map((t) => (t === 'Mod' ? 'Cmd' : t)).join('+');
   222	    const n = kb.normalizeKeybindingWithOptions(cmd, kb.normalizeOptionsForAction(def.id));
   223	    if (!n.ok) throw new Error(`${def.id}: ${cmd}: ${n.error}`);
   224	    return n.value;
   225	  });
   226	  const free = mac.filter((b) => !isTaken(def.id, b));
   227	  if (free.length < mac.length) {
   228	    console.error(`${def.id}: ${mac.filter((b) => isTaken(def.id, b)).join(', ')} is Hyprland's`);
   229	  }
   230	  // Every chord taken: leave the action on its Linux default rather than
   231	  // unbinding it. No macOS binding at all is different -- unbound there, so
   232	  // unbound here ([]). Same as the Linux default: nothing to say.
   233	  if (mac.length > 0 && free.length === 0) {
   234	    fellBack.add(def.id);
   235	    continue;
   236	  }
   237	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
   238	  overrides[def.id] = free;
   239	}
   240	
   241	// A fallback can land on a generated chord the Mac table never had to keep
   242	// apart from it. Orca dispatches some actions across scopes, ahead of the
   243	// conflict check's scope groups -- the workspace digits before the tab
   244	// digits -- so with Super+1..9 Hyprland's, workspace.selectByIndex stays on
   245	// Ctrl+1..9 and the Mac tab.selectByIndex (Ctrl+1..9) would never fire.
   246	// Such an action goes back to its own Linux default too, until none is left.
   247	const identities = (id, bindings) =>
   248	  bindings.flatMap((b) => kb.keybindingConflictIdentities(id, b, 'linux'));
   249	for (;;) {
   250	  const held = new Set(
   251	    [...fellBack].flatMap((id) => identities(id, kb.getDefaultBindings(kb.getKeybindingDefinition(id), 'linux'))),
   252	  );
   253	  const shadowed = Object.keys(overrides).filter((id) => identities(id, overrides[id]).some((i) => held.has(i)));
   254	  if (shadowed.length === 0) break;
   255	  for (const id of shadowed) {
   256	    console.error(`${id}: ${overrides[id].join(', ')} is a fallen-back Linux default's`);
   257	    delete overrides[id];
   258	    fellBack.add(id);
   259	  }
   260	}
   261	
   262	// Orca drops every action in a conflicting set at load, with only a line in
   263	// its diagnostics; fail the build instead.
   264	const conflicts = kb.findKeybindingConflicts('linux', overrides);
   265	if (conflicts.length > 0) {
   266	  throw new Error(`conflicting shortcuts: ${JSON.stringify(conflicts)}`);
   267	}
   268	process.stdout.write(`${JSON.stringify(overrides, null, 2)}\n`);
